"""
Lightweight pandas compatibility helpers for hana_ml.

Provides version detection and small shims to keep behavior stable
across pandas 2.x and 3.x without impacting older versions.
"""

#pylint: disable=invalid-name

import re
import warnings
from typing import Any, Optional, Tuple, Dict, List


def get_pandas_version() -> Optional[str]:
    """Return installed pandas version string, or None if pandas is missing."""
    try:
        import pandas as pd  # type: ignore  # pylint: disable=unused-import
    except Exception:
        return None
    return getattr(pd, "__version__", None)


def _version_tuple(v: str) -> Tuple[int, int, int]:
    """Extract (major, minor, patch) from a version string like '3.0.1' or '3.0.0rc1'."""
    m = re.match(r"^(\d+)\.(\d+)(?:\.(\d+))?", v)
    if not m:
        return (0, 0, 0)
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3)) if m.group(3) is not None else 0
    return (major, minor, patch)


def is_pandas_ge(major: int, minor: int = 0, patch: int = 0) -> bool:
    """True if installed pandas version >= (major, minor, patch)."""
    v = get_pandas_version()
    if v is None:
        return False
    return _version_tuple(v) >= (major, minor, patch)


def is_pandas3() -> bool:
    """True if pandas >= 3.0."""
    return is_pandas_ge(3, 0, 0)


def to_numpy(obj: Any):
    """
    Convert pandas Series/DataFrame/Index to a NumPy ndarray in a
    version-stable way. Falls back to np.asarray for non-pandas objects.
    """
    try:
        # pandas 0.24+ provides .to_numpy on Series/DataFrame/Index
        return obj.to_numpy()  # type: ignore
    except AttributeError:
        import numpy as np  # type: ignore
        return np.asarray(obj)


def sanitize_read_csv_kwargs(kwargs: Dict[str, Any]) -> Dict[str, Any]:
    """
    Remove read_csv kwargs that are removed or deprecated in newer pandas versions.

    This function is idempotent and safe to call for any pandas version.
    """
    if not isinstance(kwargs, dict):
        return kwargs
    # Params removed across recent versions; guard them for forward-compat.
    removed = {
        # Removed long ago, ensure we don't pass them under pandas>=1.3 and 3.0
        "error_bad_lines",
        "warn_bad_lines",
        # Datetime parsing deprecations/removals
        "date_parser",
        "infer_datetime_format",
        "keep_date_col",
    }
    for k in list(kwargs.keys()):
        if k in removed:
            kwargs.pop(k, None)
    return kwargs


def check_pandas_compat() -> None:
    """
    Perform a lightweight runtime check and warn about pandas 3.0 specifics.

    - If pandas is missing: warn once.
    - If pandas>=3.0: warn about potential ExtensionArray behavior and CoW.
    """
    v = get_pandas_version()
    if v is None:
        warnings.warn(
            "pandas is not installed; hana_ml will operate with limited features.",
            RuntimeWarning,
        )
        return
    if is_pandas3():
        warnings.warn(
            (
                "Detected pandas %s. Note: string columns may use ExtensionArray and "
                "Copy-on-Write semantics are enabled by default. hana_ml aims to be compatible "
                "but if you encounter issues with .values on Series, prefer .to_numpy()/.array."
            )
            % v,
            RuntimeWarning,
        )


def stringify_series(series: Any):
    """
    Convert a pandas Series to string values while preserving missing values.

    - Under pandas>=3.0, use `map(str, na_action='ignore')` to avoid coercing NA
      to 'nan'.
    - Under older versions, fall back to `astype(str)` to preserve legacy behavior.
    """
    try:
        import pandas as pd  # pylint: disable=unused-import
    except Exception:
        return series
    if is_pandas3():
        return series.map(str, na_action='ignore')
    return series.astype(str)


def to_str_list(series: Any) -> List[Any]:
    """
    Produce a Python list of stringified values from a pandas Series while
    preserving missing values as None.
    """
    try:
        import pandas as pd  # pylint: disable=unused-import
    except Exception:
        return list(series)
    s = stringify_series(series)
    # Replace pandas NA with None so downstream JSON/JS consumers don't see '<NA>'.
    try:
        s = s.where(~s.isna(), None)
    except Exception:
        pass
    return list(s.tolist())


def select_string_columns(df: Any):
    """
    Select string-like columns from a pandas DataFrame.

    - pandas>=3.0: include both 'object' and 'string' dtypes
    - older versions: include only 'object'
    """
    inc = ['object', 'string'] if is_pandas3() else ['object']
    try:
        return df.select_dtypes(include=inc)
    except Exception:
        return df


def to_str_list_compat(series: Any) -> List[Any]:
    """
    Convert a pandas Series to a list of strings with version-compatible behavior.

    - pandas>=3.0: use to_str_list(series) to preserve missing values as None.
    - pandas<3.0: mimic legacy behavior: list(series.astype(str)).
    """
    if is_pandas3():
        return to_str_list(series)
    try:
        return list(series.astype(str))
    except Exception:
        return list(series)
